      box.querySelector('.act').insertAdjacentHTML('afterbegin', '<a class="btn pri" style="text-decoration:none;display:inline-flex;align-items:center" href="/?view=clientbook&cbq=' + encodeURIComponent(full) + '" target="_blank" rel="noopener">Open in Client Book</a>');
